#!/usr/bin/env python3
"""Embed examples/<lang>/* into examples-gen.js  (run: python3 tools/build-examples.py)."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SPEC = {
 "react": ("jsx", {"Components": {"counter-todo": "React: counter + todo", "shopping-cart": "React: shopping cart (useReducer)", "tic-tac-toe": "React: tic-tac-toe", "data-explorer": "React: data explorer"}}),
 "playcanvas": ("js", {"3D": {"spinning-cube": "PlayCanvas: spinning cube", "solar-system": "PlayCanvas: solar system", "keyboard-and-mouse": "PlayCanvas: keyboard + mouse"}}),
 "ts": ("ts", {"Pages": {"tech-landing": "Page: tech landing (Nimbus)", "social-feed": "Page: social media feed", "stock-market": "Page: stock market dashboard"}, "Basics": {"async-union": "Async + discriminated unions"}}),
 "rust": ("rs", {"Emulation": {"nes-cpu-6502": "NES: 6502 CPU emulator", "nes-tiles": "NES: tile / PPU renderer"}, "Projects": {"game-of-life": "Game of Life", "tic-tac-toe-ai": "Tic-tac-toe AI", "brainfuck": "Brainfuck interpreter", "calculator": "Expression calculator", "maze-bfs": "Maze solver (BFS)"}}),
 "java": ("java", {"Basics": {"hello-java": "Hello, Java"}, "Projects": {"bank-oop": "Bank accounts (OOP)", "sorting-visualizer": "Sorting algorithms", "threads-executor": "Threads & executors", "lru-cache": "LRU cache"}}),
 "csharp": ("cs", {"Basics": {"hello-csharp": "Hello, C#", "linq-playground": "LINQ playground"}, "Projects": {"bank-oop": "Bank accounts (OOP)", "tasks-async": "Tasks, async & parallel"}}),
 "c": ("c", {"Basics": {"hello-c": "Hello, C", "primes-and-arrays": "Primes & arrays", "matrix-and-strings": "Matrix & strings"}, "Projects": {"sorting-race": "Sorting race"}}),
 "cpp": ("cpp", {"Basics": {"hello-cpp": "Hello, C++", "shapes-and-overloads": "Overloads & shapes"}, "Projects": {"bank-account": "Bank account", "tic-tac-toe": "Tic-tac-toe bots"}}),
 "ansible": ("yml", {"Start here": {"ping-and-facts": "Ping & facts", "web-server": "Web server (nginx)"}, "Core concepts": {"variables-loops-when": "Variables, loops & when", "errors-block-rescue": "Errors: block / rescue", "forgot-become": "Mistake: forgot become"}, "Real-world": {"users-ssh-firewall": "Harden: users, ssh, firewall", "database-server": "Database server", "unreachable-host": "Unreachable host (own inventory)"}}),
 "sql": ("sql", {"SQLite": {"sqlite-hello": "SQLite: hello, temp table", "sqlite-temp-tables": "SQLite: joins with temp tables"}, "PostgreSQL": {"postgres-hello": "PostgreSQL: hello, temp table"}}),
 "shell": ("sh", {"Start here": {"hello-navigation": "Hello & navigation", "scripting-basics": "Scripting basics"}, "Text tools": {"pipes-and-text": "Pipes & text processing", "log-analysis": "Log analysis"}, "Files": {"file-management": "File management"}}),
}
out = {}
for lang, (ext, groups) in SPEC.items():
    ex, gr = {}, {}
    for g, items in groups.items():
        gr[g] = []
        for stem, title in items.items():
            with open(os.path.join(ROOT, "examples", lang, stem + "." + ext), encoding="utf-8") as f:
                ex[title] = f.read()
            gr[g].append(title)
    out[lang] = {"examples": ex, "groups": gr}
inv = os.path.join(ROOT, "examples", "ansible", "unreachable-host.ini")
out["ansible"]["inventories"] = {"Unreachable host (own inventory)": open(inv, encoding="utf-8").read()}
js = "/* GENERATED by tools/build-examples.py from examples/ — do not edit. */\nwindow.GEN = " + json.dumps(out, ensure_ascii=False).replace("</", "<\\/") + ";\n"
open(os.path.join(ROOT, "examples-gen.js"), "w", encoding="utf-8").write(js)
print("examples-gen.js", len(js), "bytes;", {k: len(v["examples"]) for k, v in out.items()})
